// ================= ICONS: custom art replaces every emoji =================
// Flat icons  -> <svg><use href="#i-key"></svg>  (inlined sprite, tinted by the surrounding text colour)
// Styled art  -> <img src="assets/icons/key.svg"> (full colour weapons / armour / sets / artifacts / emblems)
// Keys live in ICON_FLAT / ICON_STYLED (generated by art/build.js into 0_icons_gen.js).
const ICON_DIR = 'assets/icons/';
const _icoMiss = new Set();
function icoMiss(k) { if (!_icoMiss.has(k)) { _icoMiss.add(k); console.warn('[icons] missing icon key:', k); } }
/** HTML for one icon. cls adds classes (e.g. 'big'). style is optional inline css (e.g. 'color:#f80'). */
function ico(k, cls = '', style = '') {
  const st = style ? ` style="${style}"` : '';
  if (ICON_STYLED.has(k)) return `<img class="gi gs ${cls}" src="${ICON_DIR}${k}.svg" alt="" draggable="false"${st}>`;
  if (ICON_FLAT.has(k)) return `<svg class="gi ${cls}" aria-hidden="true"${st}><use href="#i-${k}"/></svg>`;
  icoMiss(k); return '';
}
/** the styled-art key for an item (weapon / armour / set piece / artifact), tier picked from rarity */
function itemIconKey(it) {
  if (!it) return '';
  if (it.art && ICON_STYLED.has('x-' + it.art)) return 'x-' + it.art;
  if (it.set && ICON_STYLED.has(`s-${it.set}-${it.slot}`)) return `s-${it.set}-${it.slot}`;
  const t = RAR_TIER[Math.min(RAR_TIER.length - 1, it.r || 0)] || 1;
  if (it.slot === 'weapon' || it.slot === 'weapon2') return `w-${it.t}-t${t}`;
  const w = (typeof wgtOf === 'function' && wgtOf(it)) || it.wgt;
  if (w && ICON_STYLED.has(`a-${it.slot}-${w}-t${t}`)) return `a-${it.slot}-${w}-t${t}`;
  return `a-${it.t || it.slot}-t${t}`;
}
/** layered item art: base icon + legendary-power emblem + infusion glow */
function itemIcon(it, cls = '') {
  if (!it) return '';
  const k = itemIconKey(it), em = it.u && it.r >= 4 && !it.art && ICON_STYLED.has('e-' + it.u) ? `<img class="gi-em" src="${ICON_DIR}e-${it.u}.svg" alt="" draggable="false">` : '';
  const inf = it.inf && typeof INFUSE !== 'undefined' && INFUSE[it.inf] ? ` style="--inf:${INFUSE[it.inf].col}"` : '';
  if (!ICON_STYLED.has(k)) icoMiss(k);
  return `<span class="gi-item ${inf ? 'inf' : ''} ${cls}"${inf}><img class="gi gs" src="${ICON_DIR}${k}.svg" alt="" draggable="false">${em}</span>`;
}
/** for <canvas>: a cached Image of an icon. Flat icons are painted in `col`. Returns null until loaded. */
const _icoImgs = {};
function icoImg(k, col = '#ffffff') {
  const id = k + '|' + col; let im = _icoImgs[id];
  if (!im) {
    im = _icoImgs[id] = new Image();
    if (ICON_STYLED.has(k)) im.src = ICON_DIR + k + '.svg';
    else { const s = document.getElementById('i-' + k); if (!s) { icoMiss(k); return null; }
      im.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" fill="${col}">${s.innerHTML}</svg>`); }
  }
  return im.complete && im.naturalWidth ? im : null;
}
/** draw an icon centred at x,y on a 2D canvas context */
function drawIco(X, k, x, y, size, col) { const im = icoImg(k, col); if (im) X.drawImage(im, x - size / 2, y - size / 2, size, size); }
// warm the browser cache for styled art so inventory icons never pop in
function preloadIcons() { // a few at a time, so slow/simple servers aren't flooded
  const q = [...ICON_STYLED]; let live = 0;
  const next = () => { while (live < 6 && q.length) { live++; const im = new Image(); im.onload = im.onerror = () => { live--; next(); }; im.src = ICON_DIR + q.shift() + '.svg'; } };
  next();
}
addEventListener('load', () => setTimeout(preloadIcons, 500));
/** strip icon markup from a string — for title="" attributes, canvas text, document.title, plain-text chat */
function plain(s) { return String(s == null ? '' : s).replace(/<svg[\s\S]*?<\/svg>|<img[^>]*>|<span class="gi-item[^"]*"[^>]*>[\s\S]*?<\/span>/g, '').replace(/\s{2,}/g, ' ').trim(); }
/** recover the icon key from ico() html (e.g. a data table's `ic` field) — for drawIco on canvas */
function icoKeyOf(html) { const m = /#i-([\w-]+)|icons\/([\w-]+)\.svg/.exec(String(html || '')); return m ? (m[1] || m[2]) : ''; }
